test('queued repeated shortcuts traverse the original MRU snapshot before one commit', async t => {
  const { controller, state } = await setup(t);
  await Promise.all([
    controller.enqueue(() => controller.begin(1, false, { id: 4 })),
    controller.enqueue(() => controller.begin(1, false, { id: 4 })),
    controller.enqueue(() => controller.begin(1, false, { id: 4 })),
  ]);
  assert.deepEqual(controller.session.selection.ids, [4, 3, 2, 1]);
  assert.equal(selectedId(controller.session.selection), 1);
  assert.equal(state.popupCalls.length, 1);
  assert.deepEqual(state.updates, [], 'highlights do not activate tabs');
  assert.equal((await controller.commit()).ok, true);
  assert.deepEqual(state.updates, [{ id: 1, changes: { active: true } }]);
  assert.deepEqual(controller.history[10], [1, 4, 3, 2]);
  assert.equal(controller.session, null);
});

test('toolbar popup creates a manual session and ignores modifier releases', async t => {
  const { controller, popup, overlay, state } = await setup(t);
  const response = await controller.message({ type: 'ui-ready', surface: 'popup' }, popup);
  assert.equal(response.ok, true);
  assert.equal(response.session.mode, 'manual');
  assert.deepEqual(response.tabs.map(tab => tab.id), [4, 3, 2, 1]);
  assert.equal(selectedId(controller.session.selection), 3);
  await controller.message({ type: 'modifier-released', at: Date.now() + 10 }, overlay);
  assert.equal(controller.session.mode, 'manual');
  assert.deepEqual(state.updates, []);
  await controller.message({ type: 'commit', sessionId: controller.session.id, tabId: 2 }, popup);
  assert.equal(state.updates.at(-1).id, 2);
});

