test('an activation event invalidates an in-flight screenshot even when original tab becomes active again', async t => {
  const { controller } = await setup(t, { permission: true, local: { previewsEnabled: true } });
  let decoding;
  const decodeStarted = new Promise(resolve => { decoding = resolve; });
  let finish;
  const decodeGate = new Promise(resolve => { finish = resolve; });
  mockImageRuntime(t, async () => { decoding(); await decodeGate; });
  const capturing = controller.capture(4);
  await decodeStarted;
  // background.js increments this immediately at the Chrome event boundary,
  // before queued activation handlers or a screenshot save can run.
  controller.captureGeneration++;
  await controller.activated({ tabId: 3, windowId: 10 });
  controller.captureGeneration++;
  await controller.activated({ tabId: 4, windowId: 10 });
  finish();
  await capturing;
  assert.deepEqual(controller.cache, {});
});
